import json import sqlite3 import os from pathlib import Path from dataclasses import dataclass, field from datetime import datetime, timedelta from typing import List, Dict, Optional, Any
import anyio
# ─── Data Models ──────────────────────────────────────────────────────────────
@dataclass class MetricSeries: timestamps: List[float] values: List[float]
@dataclass class TraceEvent: timestamp: str level: str entity: str message: str trace_id: str raw: Dict[str, Any]
@dataclass class TokenBurn: prompt_tokens: int completion_tokens: int cost_usd: float provider_name: str
@dataclass class CognitiveVelocity: tokens_per_second: float acceleration: float # Rate of change (tokens/sec^2)
@dataclass class FleetHealth: breaker_states: Dict[str, str] global_error_rate: float
# ─── Custom Errors ────────────────────────────────────────────────────────────
class ObservabilityError(Exception): """Base error for observability reader failures.""" pass
class DatabaseLockedError(ObservabilityError): """Raised if the database is locked despite read-only mode.""" pass
# ─── Main Reader Class ────────────────────────────────────────────────────────
class SovereignReader: def __init__(self, db_path: Path, trace_dir: Path, crash_dir: Path): self.db_path = db_path self.trace_dir = trace_dir self.crash_dir = crash_dir
def _get_connection(self) -> sqlite3.Connection: """Returns a read-only SQLite connection to prevent locking the WAL.""" if not self.db_path.exists(): # Return an in-memory DB if it doesn't exist yet to prevent crashes return sqlite3.connect(":memory:")
try: # URI mode required for ?mode=ro conn = sqlite3.connect(f"file:{self.db_path.absolute()}?mode=ro", uri=True) conn.row_factory = sqlite3.Row return conn except sqlite3.Error as e: raise ObservabilityError(f"Failed to connect to metrics DB: {e}")
# ─── Metrics & TSDB Queries ───────────────────────────────────────────────
def _sync_get_metric_series(self, metric_name: str, entity_id: Optional[str], window_mins: int) -> MetricSeries: cutoff = (datetime.utcnow() - timedelta(minutes=window_mins)).timestamp()
query = "SELECT timestamp, value FROM metrics WHERE metric_name = ? AND timestamp >= ?" params = [metric_name, cutoff]
if entity_id: query += " AND entity_id = ?" params.append(entity_id)
query += " ORDER BY timestamp ASC"
try: with self._get_connection() as conn: # Check if table exists first (graceful degradation) cur = conn.cursor() cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='metrics'") if not cur.fetchone(): return MetricSeries(timestamps=[], values=[])
cur.execute(query, params) rows = cur.fetchall() return MetricSeries( timestamps=[r["timestamp"] for r in rows], values=[r["value"] for r in rows] ) except sqlite3.Error as e: raise ObservabilityError(f"Database query failed: {e}")
async def get_metric_series(self, metric_name: str, entity_id: Optional[str] = None, window_mins: int = 60) -> MetricSeries: return await anyio.to_thread.run_sync(self._sync_get_metric_series, metric_name, entity_id, window_mins)
def _sync_get_fleet_health(self) -> FleetHealth: # In a full implementation, this would query a circuit_breakers table and error metrics. # For now, we scaffold the query structure. breaker_states = {} error_rate = 0.0
try: with self._get_connection() as conn: cur = conn.cursor()
# Scaffold: get latest breaker states cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='circuit_breakers'") if cur.fetchone(): cur.execute("SELECT provider, state FROM circuit_breakers") breaker_states = {r["provider"]: r["state"] for r in cur.fetchall()}
# Scaffold: calculate error rate over last 5 mins cutoff = (datetime.utcnow() - timedelta(minutes=5)).timestamp() cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='metrics'") if cur.fetchone(): cur.execute("SELECT COUNT(*) as total, SUM(CASE WHEN metric_name = 'error' THEN 1 ELSE 0 END) as errors FROM metrics WHERE timestamp >= ?", (cutoff,)) row = cur.fetchone() if row and row["total"] > 0: error_rate = row["errors"] / row["total"]
except sqlite3.Error as e: # Graceful degradation if tables don't exist yet pass
return FleetHealth(breaker_states=breaker_states, global_error_rate=error_rate)
async def get_fleet_health(self) -> FleetHealth: return await anyio.to_thread.run_sync(self._sync_get_fleet_health)
# ─── Token & Cost Attribution ─────────────────────────────────────────────
def _sync_get_entity_cost(self, entity_id: str, session_id: Optional[str]) -> TokenBurn: query = "SELECT SUM(prompt_tokens) as p, SUM(completion_tokens) as c, SUM(cost_usd) as cost, provider_name FROM token_ledger WHERE entity_id = ?" params = [entity_id]
if session_id: query += " AND session_id = ?" params.append(session_id)
query += " GROUP BY provider_name"
try: with self._get_connection() as conn: cur = conn.cursor() cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='token_ledger'") if not cur.fetchone(): return TokenBurn(0, 0, 0.0, "unknown")
cur.execute(query, params) rows = cur.fetchall()
if not rows: return TokenBurn(0, 0, 0.0, "unknown")
# Aggregate across providers if multiple p_tokens = sum(r["p"] for r in rows if r["p"]) c_tokens = sum(r["c"] for r in rows if r["c"]) total_cost = sum(r["cost"] for r in rows if r["cost"]) # Just take the most recent/dominant provider for the summary provider = rows[0]["provider_name"]
return TokenBurn(p_tokens, c_tokens, total_cost, provider) except sqlite3.Error as e: raise ObservabilityError(f"Token ledger query failed: {e}")
async def get_entity_cost(self, entity_id: str, session_id: Optional[str] = None) -> TokenBurn: return await anyio.to_thread.run_sync(self._sync_get_entity_cost, entity_id, session_id)
def _sync_get_cognitive_velocity(self, entity_id: str, window_secs: int = 30) -> CognitiveVelocity: """Calculates tokens/sec and acceleration (change in tokens/sec) to detect loops.""" now = datetime.utcnow().timestamp() t1 = now - window_secs t2 = now - (window_secs * 2)
query = """ SELECT SUM(CASE WHEN timestamp >= ? THEN prompt_tokens + completion_tokens ELSE 0 END) as window1_tokens, SUM(CASE WHEN timestamp >= ? AND timestamp < ? THEN prompt_tokens + completion_tokens ELSE 0 END) as window2_tokens FROM token_ledger WHERE entity_id = ? AND timestamp >= ? """
try: with self._get_connection() as conn: cur = conn.cursor() cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='token_ledger'") if not cur.fetchone(): return CognitiveVelocity(0.0, 0.0)
cur.execute(query, (t1, t2, t1, entity_id, t2)) row = cur.fetchone()
w1_tokens = row["window1_tokens"] or 0 w2_tokens = row["window2_tokens"] or 0
v1 = w1_tokens / window_secs v2 = w2_tokens / window_secs
acceleration = (v1 - v2) / window_secs
return CognitiveVelocity(tokens_per_second=v1, acceleration=acceleration) except sqlite3.Error as e: raise ObservabilityError(f"Velocity calculation failed: {e}")
async def get_cognitive_velocity(self, entity_id: str, window_secs: int = 30) -> CognitiveVelocity: return await anyio.to_thread.run_sync(self._sync_get_cognitive_velocity, entity_id, window_secs)
# ─── Forensic Trace Tailing (JSONL) ───────────────────────────────────────
def _sync_tail_live_traces(self, max_lines: int) -> List[TraceEvent]: """O(1) reverse-binary scan of the active daily event file.""" # Events are written to data/logs/events/YYYY-MM-DD.jsonl today = datetime.utcnow().strftime("%Y-%m-%d") trace_file = self.trace_dir.parent / "logs" / "events" / f"{today}.jsonl"
if not trace_file.exists(): return []
events = [] chunk_size = 8192
try: with open(trace_file, "rb") as f: f.seek(0, os.SEEK_END) file_size = f.tell() position = file_size buffer = b""
while position > 0 and len(events) < max_lines: read_size = min(chunk_size, position) position -= read_size f.seek(position) chunk = f.read(read_size) buffer = chunk + buffer
lines = buffer.split(b"\n") # The first element might be an incomplete line, save it for the next iteration buffer = lines.pop(0)
# Process lines in reverse for line in reversed(lines): if not line.strip(): continue if len(events) >= max_lines: break try: data = json.loads(line.decode("utf-8")) # Extract the actual event data from the wrapped format event_data = data.get("data", data) events.append(TraceEvent( timestamp=data.get("timestamp", ""), level=event_data.get("level", "INFO"), entity=event_data.get("entity", "system"), message=event_data.get("message", str(event_data)[:200]), trace_id=data.get("trace_id", "unknown"), raw=data )) except json.JSONDecodeError: continue
# Handle the last remaining buffer if we haven't hit max_lines if buffer.strip() and len(events) < max_lines: try: data = json.loads(buffer.decode("utf-8")) event_data = data.get("data", data) events.append(TraceEvent( timestamp=data.get("timestamp", ""), level=event_data.get("level", "INFO"), entity=event_data.get("entity", "system"), message=event_data.get("message", str(event_data)[:200]), trace_id=data.get("trace_id", "unknown"), raw=data )) except json.JSONDecodeError: pass
except IOError as e: raise ObservabilityError(f"Failed to tail traces: {e}")
# Reverse again to return in chronological order (oldest to newest among the tail) return list(reversed(events))
async def tail_live_traces(self, max_lines: int = 50) -> List[TraceEvent]: return await anyio.to_thread.run_sync(self._sync_tail_live_traces, max_lines)
def _sync_get_crash_dump(self, trace_id: str) -> Optional[Dict[str, Any]]: """Retrieves a specific crash dump from the bleg directory.""" # Sanitize trace_id to prevent path traversal safe_trace_id = "".join(c for c in trace_id if c.isalnum() or c in "-_") dump_file = self.crash_dir / f"{safe_trace_id}.json"
if not dump_file.exists(): return None
try: with open(dump_file, "r", encoding="utf-8") as f: return json.load(f) except (IOError, json.JSONDecodeError) as e: raise ObservabilityError(f"Failed to read crash dump {safe_trace_id}: {e}")
async def get_crash_dump(self, trace_id: str) -> Optional[Dict[str, Any]]: return await anyio.to_thread.run_sync(self._sync_get_crash_dump, trace_id)

# 🔱 Body-Level Error Guards (BLEG)
# AP: AP-BLEG-v1.0.0
# ⬡ OMEGA ⬡ KALI ⬡ bleg ⬡ OBSERVABILITY
#
# Middleware that inspects HTTP 200 (OK) response bodies for error
# signatures. Many cloud APIs return HTTP 200 with an error payload
# when quota is exhausted or auth is invalid — BLEG catches these
# "Silent 200s" and converts them to typed OmegaErrors so the circuit
# breaker trips correctly.
#
# [M9 Error Integrity] — No error goes undetected, even in a 200 OK.
# [M22 Response Provenance] — Every detected error records the provider.
#
# [id-soft: quake-1996] Right Approximation — a simple JSON-keyword
# scan is "good enough" for 99% of cases. Full schema validation is
# not needed at this layer.

# DocRef: docs/explanation/metrics-pipeline.md
import json
import logging
from typing import Any, Dict, Optional
from omega.errors import ProviderError, ProviderRateLimitError, ProviderAuthError
from omega.observability.ufl import get_ufl_writer

logger = logging.getLogger(__name__)

# ── Error signatures to scan in response bodies ──────────────────────
# Each entry is (keyword_path, error_factory).
# keyword_path is a dot-separated path into the JSON body.
# If the key exists AND its value is truthy, the factory is called.

ERROR_SIGNATURES: Dict[str, tuple] = {
    # Numeric code matches FIRST — exact status codes.
    "error.code": {                            # {"error": {"code": 429}}
        429: ProviderRateLimitError,
        401: ProviderAuthError,
        403: ProviderAuthError,
    },
    "code": {                                  # {"code": 429}
        429: ProviderRateLimitError,
        401: ProviderAuthError,
        403: ProviderAuthError,
    },
    "status": {                                # {"status": 429}
        429: ProviderRateLimitError,
        401: ProviderAuthError,
        403: ProviderAuthError,
    },
    # Keyword matches — rate limit indicators.
    "quota_exceeded": (None, ProviderRateLimitError),  # {"quota_exceeded": true}
    "error.type": (                            # {"error": {"type": "rate_limit_error"}}
        "rate_limit", ProviderRateLimitError
    ),
    # Generic string matches — last resort.
    "error.message": (None, ProviderError),    # {"error": {"message": ...}}
    "error": ("__string__", ProviderError),    # {"error": "string message"}
}

class BLEGMiddleware:
    """Body-Level Error Guard — inspects HTTP 200 OK bodies for errors.

    This is NOT an ASGI/WSGI middleware. It's a response inspection
    function to be called after any httpx (or similar) request, before
    the caller processes the response.

    Usage::

        guard = BLEGMiddleware()
        response = await client.post(...)
        guard.inspect(response, provider="firecrawl", trace_id="trc_abc")
        # If a Silent 200 was detected, inspect() raises the error.
    """

    def __init__(self, enabled: bool = True):
        self._enabled = enabled
        self._ledger = get_ufl_writer() if enabled else None

    def inspect(
        self,
        status_code: int,
        body: Any,
        provider: str = "unknown",
        trace_id: str = "unknown",
        url: str = "",
    ) -> None:
        """Inspect an HTTP response body for error signatures.

        Args:
            status_code: The HTTP status code.
            body: The response body — JSON-deserialized dict, a string,
                or bytes. Strings/bytes will be parsed as JSON if possible.
            provider: The provider name for error attribution.
            trace_id: Current trace_id for forensic logging.
            url: The request URL for diagnostic context.

        Raises:
            ProviderRateLimitError: If a rate-limit error signature is found.
            ProviderAuthError: If an auth error signature is found.
            ProviderError: If a generic error signature is found.
        """
        if not self._enabled:
            return

        # Only inspect 200-range responses for Silent 200s
        if not (200 <= status_code < 300):
            return

        # Parse the body if needed
        parsed = self._parse_body(body)
        if parsed is None:
            return  # Body is not JSON — nothing to inspect

        # Scan for error signatures
        error_info = self._scan_for_errors(parsed)
        if error_info is None:
            return  # No error signature found

        error_cls, message = error_info

        # Log the silent failure to the forensic ledger
        if self._ledger:
            self._ledger.write(
                event_type="silent_200",
                trace_id=trace_id,
                provider=provider,
                payload={
                    "url": url,
                    "status_code": status_code,
                    "error_signature": error_cls.__name__,
                    "error_message": message[:300],
                    "body_sample": str(parsed)[:500],
                },
            )

        # Raise the typed error so the circuit breaker trips
        raise error_cls(provider, message)

    # ── Internal ───────────────────────────────────────────────────

    @staticmethod
    def _parse_body(body: Any) -> Optional[Dict[str, Any]]:
        """Parse a response body into a dict if it's JSON."""
        if isinstance(body, dict):
            return body
        if isinstance(body, bytes):
            body = body.decode("utf-8", errors="replace")
        if isinstance(body, str):
            try:
                return json.loads(body)
            except (json.JSONDecodeError, ValueError):
                return None
        return None

    @staticmethod
    def _scan_for_errors(parsed: Dict[str, Any]) -> Optional[tuple]:
        """Scan a parsed JSON dict for known error signatures.

        Returns (error_class, message) if a signature matches, else None.
        """
        # Check each signature path
        for path, match_spec in ERROR_SIGNATURES.items():
            value = _get_nested(parsed, path)
            if value is None:
                continue

            # Determine the error message from a meaningful source
            msg = str(value) if isinstance(value, (str, int, float)) else str(
                parsed.get("error", {}).get("message",
                parsed.get("message", str(parsed)))
            )

            if isinstance(match_spec, dict):
                # Dict-based numeric code match
                try:
                    int_val = int(value)
                    if int_val in match_spec:
                        return (match_spec[int_val], msg[:500])
                except (ValueError, TypeError):
                    continue

            elif isinstance(match_spec, tuple):
                match_value, error_cls = match_spec

                if match_value == "__string__":
                    # Generic "error" key — only match if value is a string
                    if isinstance(value, str) and value:
                        return (error_cls, value[:500])
                    continue

                if match_value is None:
                    # Any truthy value at this path is an error
                    if value:
                        return (error_cls, msg[:500])

                elif isinstance(match_value, str):
                    # String match — check if value CONTAINS the keyword
                    # e.g. "rate_limit_error" contains "rate_limit"
                    str_val = str(value).lower()
                    keyword = match_value.lower()
                    if keyword in str_val or keyword.replace("_", "") in str_val:
                        return (error_cls, msg[:500])

        return None

def _get_nested(d: Dict[str, Any], path: str) -> Any:
    """Get a nested value from a dict using dot-separated path."""
    parts = path.split(".")
    current = d
    for part in parts:
        if isinstance(current, dict) and part in current:
            current = current[part]
        else:
            return None
    return current

# 🔱 Omega Engine — Sovereignty Ratio Query ([DRIVERS_LICENSE_1]) # AP: AP-SOVEREIGNTY-RATIO-v1.0.0 # ⬡ OMEGA ⬡ RESEARCHER ⬡ hy3-free ⬡ opencode ⬡ trc_research # # Queries MetricsDB performance table for local vs cloud inference ratio. # The `is_cloud` field is set per-response by the ModelGateway (M22 provenance). # Local=0, Cloud=1. # # [id-soft: quake3-1999] cvar — sovereignty ratio as a cvar-table metric
import logging import sqlite3 from pathlib import Path from typing import Dict, Any from datetime import datetime, timezone
logger = logging.getLogger(__name__)
# Default MetricsDB location (matches MetricsDB class default) METRICS_DB_PATH = Path("data/observability/metrics.db")
def get_sovereignty_ratio( db_path: str | Path = METRICS_DB_PATH, since_days: int | None = None, ) -> Dict[str, Any]: """ Query the local vs cloud inference ratio from MetricsDB.
Args: db_path: Path to the MetricsDB SQLite database. since_days: Optional — only count inferences from last N days.
Returns: Dict with keys: local_count, cloud_count, total, ratio_local, ratio_cloud, provider_breakdown, since, generated_at. Returns empty counts if DB doesn't exist or has no data. """ db = Path(db_path) if not db.exists(): logger.warning(f"MetricsDB not found at {db_path}") return { "local_count": 0, "cloud_count": 0, "total": 0, "ratio_local": 0.0, "ratio_cloud": 0.0, "provider_breakdown": {}, "since": "no_data", "generated_at": datetime.now(timezone.utc).isoformat(), }
try: conn = sqlite3.connect(str(db)) conn.row_factory = sqlite3.Row cur = conn.cursor()
# Check if performance table exists cur.execute( "SELECT name FROM sqlite_master WHERE type='table' AND name='performance'" ) if not cur.fetchone(): conn.close() return { "local_count": 0, "cloud_count": 0, "total": 0, "ratio_local": 0.0, "ratio_cloud": 0.0, "provider_breakdown": {}, "since": "no_table", "generated_at": datetime.now(timezone.utc).isoformat(), }
# Time filter since_ts = None if since_days: since_ts = ( datetime.now(timezone.utc).timestamp() - since_days * [ZIP_CODE_1] )
# Aggregate counts if since_ts: cur.execute( """ SELECT SUM(CASE WHEN is_cloud = 0 THEN 1 ELSE 0 END) as local_count, SUM(CASE WHEN is_cloud = 1 THEN 1 ELSE 0 END) as cloud_count, COUNT(*) as total FROM performance WHERE ts >= ? """, (since_ts,), ) else: cur.execute( """ SELECT SUM(CASE WHEN is_cloud = 0 THEN 1 ELSE 0 END) as local_count, SUM(CASE WHEN is_cloud = 1 THEN 1 ELSE 0 END) as cloud_count, COUNT(*) as total FROM performance """ )
row = cur.fetchone() local_count = row["local_count"] or 0 cloud_count = row["cloud_count"] or 0 total = row["total"] or 0
# Provider breakdown if since_ts: cur.execute( """ SELECT provider, is_cloud, COUNT(*) as cnt FROM performance WHERE ts >= ? GROUP BY provider, is_cloud ORDER BY cnt DESC """, (since_ts,), ) else: cur.execute( """ SELECT provider, is_cloud, COUNT(*) as cnt FROM performance GROUP BY provider, is_cloud ORDER BY cnt DESC """ )
provider_breakdown = {} for prow in cur.fetchall(): provider_breakdown[prow["provider"]] = { "count": prow["cnt"], "is_cloud": bool(prow["is_cloud"]), }
conn.close()
ratio_local = local_count / max(total, 1) ratio_cloud = cloud_count / max(total, 1)
return { "local_count": local_count, "cloud_count": cloud_count, "total": total, "ratio_local": round(ratio_local, 4), "ratio_cloud": round(ratio_cloud, 4), "provider_breakdown": provider_breakdown, "since": f"last_{since_days}_days" if since_days else "all_time", "generated_at": datetime.now(timezone.utc).isoformat(), }
except sqlite3.Error as e: logger.error(f"MetricsDB query failed: {e}") return { "local_count": 0, "cloud_count": 0, "total": 0, "ratio_local": 0.0, "ratio_cloud": 0.0, "provider_breakdown": {}, "error": str(e), "generated_at": datetime.now(timezone.utc).isoformat(), }
